// ============ FILTER AND UTILITY FUNCTIONS ============

export function getAllTags(wedges: DemonWedge[]): string[] {
  const tagSet = new Set<string>();
  wedges.forEach(w => {
    w.tags.forEach(tag => tagSet.add(tag));
  });
  return Array.from(tagSet).sort();
}

export function getAllTypes(wedges: DemonWedge[]): DemonWedgeType[] {
  const typeSet = new Set<DemonWedgeType>();
  wedges.forEach(w => typeSet.add(w.type));
  return Array.from(typeSet);
}

export function getAllElements(wedges: DemonWedge[]): DemonWedgeElement[] {
  const elementSet = new Set<DemonWedgeElement>();
  wedges.forEach(w => {
    if (w.element) elementSet.add(w.element);
  });
  return Array.from(elementSet).sort();
}

export interface CategoryStat {
  category: DemonWedgeCategory;
  label: string;
  count: number;
}

const CATEGORY_LABELS: Record<DemonWedgeCategory, string> = {
  'character': 'Character',
  'melee-weapon': 'Melee Weapon',
  'ranged-weapon': 'Ranged Weapon',
  'melee-consonance': 'Melee Consonance Weapon',
  'ranged-consonance': 'Ranged Consonance Weapon',
};

export function getCategoryStats(wedges: DemonWedge[] = allDemonWedges): CategoryStat[] {
  const counts: Record<DemonWedgeCategory, number> = {
    'character': 0,
    'melee-weapon': 0,
    'ranged-weapon': 0,
    'melee-consonance': 0,
    'ranged-consonance': 0,
  };

  wedges.forEach(w => {
    counts[w.category] = (counts[w.category] ?? 0) + 1;
  });

  return (Object.keys(CATEGORY_LABELS) as DemonWedgeCategory[]).map(category => ({
    category,
    label: CATEGORY_LABELS[category],
    count: counts[category] || 0,
  }));
}

export interface FilterOptions {
  search?: string;
  types?: DemonWedgeType[];
  rarities?: DemonWedgeRarity[];
  elements?: DemonWedgeElement[];
  tags?: string[];
  usage?: DemonWedgeUsage[];
  categories?: DemonWedgeCategory[];
}

export function filterDemonWedges(wedges: DemonWedge[], options: FilterOptions): DemonWedge[] {
  // First, apply all non-search filters
  let results = wedges.filter(wedge => {
    // Category filter
    if (options.categories && options.categories.length > 0) {
      if (!options.categories.includes(wedge.category)) return false;
    }

    // Type filter
    if (options.types && options.types.length > 0) {
      if (!options.types.includes(wedge.type)) return false;
    }

    // Rarity filter
    if (options.rarities && options.rarities.length > 0) {
      if (!options.rarities.includes(wedge.rarity)) return false;
    }

    // Element filter
    if (options.elements && options.elements.length > 0) {
      if (!wedge.element || !options.elements.includes(wedge.element)) return false;
    }

    // Tag filter
    if (options.tags && options.tags.length > 0) {
      if (!options.tags.some(tag => wedge.tags.includes(tag))) return false;
    }

    // Usage filter
    if (options.usage && options.usage.length > 0) {
      if (!options.usage.includes(wedge.usage)) return false;
    }

    return true;
  });

  // Enhanced search filter with multi-word support and relevance scoring
  if (options.search && options.search.trim()) {
    const searchLower = options.search.toLowerCase().trim();

    // Split search into terms (support multi-word search)
    // Each word must match somewhere in the wedge data
    const searchTerms = searchLower.split(/\s+/).filter(term => term.length > 0);

    // Filter wedges that match all search terms
    results = results.filter(wedge => matchesSearchTerms(wedge, searchTerms));

    // Sort by relevance score (highest score first = most relevant)
    results = results
      .map(wedge => ({
        wedge,
        score: calculateRelevanceScore(wedge, searchTerms)
      }))
      .sort((a, b) => b.score - a.score)
      .map(item => item.wedge);
  }

  return results;
}

// ============================================================================
// ADVANCED SEARCH HELPERS
// ============================================================================

// Helper function to calculate relevance score for search results
function calculateRelevanceScore(wedge: DemonWedge, searchTerms: string[]): number {
  let score = 0;
  const searchLower = searchTerms.join(' ');

  // Exact name match gets highest score
  if (wedge.name.toLowerCase() === searchLower) score += 1000;
  if (wedge.fullName.toLowerCase() === searchLower) score += 900;

  // Name starts with search term
  if (wedge.name.toLowerCase().startsWith(searchLower)) score += 500;
  if (wedge.fullName.toLowerCase().startsWith(searchLower)) score += 450;

  // Name contains search term
  if (wedge.name.toLowerCase().includes(searchLower)) score += 200;
  if (wedge.fullName.toLowerCase().includes(searchLower)) score += 180;

  // Match in stats (higher score for exact stat name match)
  searchTerms.forEach(term => {
    wedge.stats.forEach(stat => {
      if (stat.name.toLowerCase() === term) score += 300;
      else if (stat.name.toLowerCase().includes(term)) score += 150;
      if (stat.value.toLowerCase().includes(term)) score += 100;
    });

    // Also search in level stats
    wedge.levels?.forEach(level => {
      level.stats.forEach(stat => {
        if (stat.name.toLowerCase().includes(term)) score += 80;
        if (stat.value.toLowerCase().includes(term)) score += 50;
      });
      if (level.description?.toLowerCase().includes(term)) score += 40;
    });
  });

  // Match in description
  if (wedge.description) {
    searchTerms.forEach(term => {
      if (wedge.description!.toLowerCase().includes(term)) score += 60;
    });
  }

  // Match in tags
  searchTerms.forEach(term => {
    wedge.tags.forEach(tag => {
      if (tag.toLowerCase() === term) score += 120;
      else if (tag.toLowerCase().includes(term)) score += 80;
    });
  });

  // Match in element, type, usage (lower priority)
  searchTerms.forEach(term => {
    if (wedge.element?.toLowerCase().includes(term)) score += 70;
    if (wedge.type.toLowerCase().includes(term)) score += 50;
    if (wedge.usage.toLowerCase().includes(term)) score += 40;
    if (wedge.category.toLowerCase().includes(term)) score += 30;
  });

  return score;
}

// Helper function to check if wedge matches all search terms
function matchesSearchTerms(wedge: DemonWedge, searchTerms: string[]): boolean {
  // Each search term must match at least one field
  return searchTerms.every(term => {
    // Search in name and fullName
    if (wedge.fullName.toLowerCase().includes(term)) return true;
    if (wedge.name.toLowerCase().includes(term)) return true;

    // Search in tags
    if (wedge.tags.some(tag => tag.toLowerCase().includes(term))) return true;

    // Search in description
    if (wedge.description?.toLowerCase().includes(term)) return true;

    // Search in base stats
    if (wedge.stats.some(stat =>
      stat.name.toLowerCase().includes(term) ||
      stat.value.toLowerCase().includes(term)
    )) return true;

    // Search in level stats (nested)
    if (wedge.levels?.some(level => {
      const matchesLevelStats = level.stats.some(stat =>
        stat.name.toLowerCase().includes(term) ||
        stat.value.toLowerCase().includes(term)
      );
      const matchesLevelDesc = level.description?.toLowerCase().includes(term);
      return matchesLevelStats || matchesLevelDesc;
    })) return true;

    // Search in element
    if (wedge.element?.toLowerCase().includes(term)) return true;

    // Search in type
    if (wedge.type.toLowerCase().includes(term)) return true;

    // Search in usage
    if (wedge.usage.toLowerCase().includes(term)) return true;

    // Search in category
    if (wedge.category.toLowerCase().includes(term)) return true;

    return false;
  });
}

// ============================================================================
// FILTER FUNCTION
// ============================================================================

export function getDemonWedgeById(id: string): DemonWedge | undefined {
  return allDemonWedges.find(w => w.id === id);
}

export function getDemonWedgesByName(name: string): DemonWedge[] {
  const lowerName = name.toLowerCase();
  return allDemonWedges.filter(w =>
    w.name.toLowerCase().includes(lowerName) ||
    w.fullName.toLowerCase().includes(lowerName)
  );
}
